'use strict';
const V = window.VAULT_SNAPSHOT;
const sections = ['Overview','Vault','Habits','Recall','Scout','Costs','Health'];
const paths = ['M3 10l9-7 9 7v10H3z M9 20v-7h6v7','M4 4h6l2 3h8v13H4z','M3 18V9m6 9V4m6 14v-6m6 6V7','M12 3v4m0 10v4M3 12h4m10 0h4M6 6l3 3m6 6l3 3M6 18l3-3m6-6l3-3','M4 5h16v12H9l-5 4z M8 9h8m-8 4h5','M12 3v18m5-14c-1-3-10-3-10 1s10 2 10 7-9 4-11 1','M3 12h4l3-7 4 14 3-7h4'];
const $ = id => document.getElementById(id);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => Number(n).toLocaleString('en-US');
const pct = (n,d) => d ? Math.round(n / d * 100) + '%' : 'Unavailable';
const dollars = n => n === null ? 'Unknown' : '$' + Number(n).toFixed(n < 1 && n > 0 ? 4 : 2);
const short = n => n >= 1000000 ? (n/1000000).toFixed(2)+'m' : n >= 1000 ? (n/1000).toFixed(1)+'k' : num(n);
let current = sections.find(x => x.toLowerCase() === location.hash.slice(1)) || 'Overview';
let demo = false, range = '30', query = '', kind = 'All', quality = 'All', order = 'date', page = 0, model = 'All', purpose = 'All';
let budget = 20, costWorkflow = 'All';
const anchorDay = V.generatedAt.slice(0,10);
const anchor = new Date(anchorDay+'T12:00:00Z');
const demoRequests = [];
const demoOperations = [];
const workflowStages = {
  'Capture processing': [['Voice','transcription'],['Vision','visual extraction'],['Classify','classification'],['Ingest','ingest planning'],['Cards','card drafting'],['Embeddings','indexing']],
  'Card creation': [['Cards','card drafting'],['Cards','card repair']],
  'Scout interaction': [['Scout','conversation'],['Scout','conversation'],['Scout','compaction'],['Scout','naming'],['Cards','card drafting']],
  'Ask': [['Embeddings','retrieval'],['Ask','answer']],
  'Direct capture': [['Voice','transcription'],['Titling','note title']],
  'Semantic search': [['Embeddings','query embedding']],
  'Recall feedback': [['Feedback','answer feedback']]
};
// Deliberately synthetic, deterministic fixtures. These are not phone observations or advertised model prices.
for (let day = 89; day >= 0; day--) {
  const date = new Date(anchor); date.setUTCDate(date.getUTCDate()-day);
  for (const [j, workflow] of Object.keys(workflowStages).entries()) {
    const id='op-'+day+'-'+j, modality=['Article','Voice','Image','Video'][day%4];
    const op={id,date:date.toISOString().slice(0,10),workflow,modality:workflow==='Capture processing'?modality:'Not applicable',
      status:day%17===0?'Failed':day%23===0?'Interrupted':'Completed',
      session:workflow==='Scout interaction'?['Agent memory research','Connect my notes','Weekly reading synthesis','Explore retrieval patterns'][day%4]:workflow,
      cardsDrafted:0,cardsSaved:0};
    demoOperations.push(op);
    for(const [step,[feature,stage]] of workflowStages[workflow].entries()) {
      if(workflow==='Capture processing'&&feature==='Voice'&&!['Voice','Video'].includes(modality))continue;
      if(workflow==='Capture processing'&&feature==='Vision'&&!['Image','Video'].includes(modality))continue;
      if(workflow==='Scout interaction'&&['compaction','naming','card drafting'].includes(stage)&&day%3!==step%3)continue;
      if(workflow==='Card creation'&&stage==='card repair'&&day%4!==0)continue;
      const retried=(day+j+step)%13===0;
      for(let attempt=0;attempt<(retried?2:1);attempt++) {
        const n=demoRequests.length, input=feature==='Voice'?null:1400+((day*317+j*1709+step*233)%22000);
        const output=feature==='Voice'?null:feature==='Embeddings'?0:180+((day*23+j*127+step*73)%2300);
        demoRequests.push({id:'demo-'+String(n+1).padStart(4,'0'),operationId:id,date:op.date,workflow,feature,stage,purpose:stage,
          model:feature==='Embeddings'?'Embedding model':feature==='Voice'?'Audio model':(day+j+step)%3===0?'Reasoning model':'Fast model',
          session:op.session,input,output,cached:input===null?null:Math.floor(input*((day+j)%4)/5),reasoning:output===null?null:Math.floor(output*((day+j)%3)/5),
          audioSeconds:feature==='Voice'?30+day%90:null,
          cost:n%19===0?null:Number(((input??3000)*.0000011+(output??300)*.0000032).toFixed(6)),
          status:retried&&attempt===0?'Error':op.status==='Completed'?'Completed':op.status,
          retry:attempt>0,attempt,duration:1200+((day*1391+j*799+step*61)%35000)});
      }
      if(feature==='Cards')op.cardsDrafted+=4+day%5;
    }
    op.cardsSaved=op.status==='Completed'?Math.max(0,op.cardsDrafted-(day%3)):0;
  }
}
function inRange(date) { if (!date) return false; if (range==='all') return true; const delta=(anchor-new Date(date+'T12:00:00Z'))/86400000; return delta>=0 && delta<Number(range); }
function rows(scoutOnly=false) { return demoRequests.filter(r=>inRange(r.date)&&(!scoutOnly||r.workflow==='Scout interaction')&&(model==='All'||r.model===model)&&(purpose==='All'||r.purpose===purpose)&&(current!=='Costs'||costWorkflow==='All'||r.workflow===costWorkflow)); }
function totals(list) {return {input:list.reduce((a,r)=>a+(r.input??0),0),output:list.reduce((a,r)=>a+(r.output??0),0),cost:list.reduce((a,r)=>a+Math.round((r.cost??0)*1e6),0)/1e6,known:list.filter(r=>r.cost!==null).length,missing:list.filter(r=>r.cost===null).length,tokenKnown:list.filter(r=>r.input!==null&&r.output!==null).length,cached:list.reduce((a,r)=>a+(r.cached??0),0),reasoning:list.reduce((a,r)=>a+(r.reasoning??0),0)};}
function operationStats(list) {
 const ids=new Set(list.map(r=>r.id)),opIds=new Set(list.map(r=>r.operationId));
 const matched=demoOperations.filter(op=>opIds.has(op.id));
 const full=matched.filter(op=>demoRequests.filter(r=>r.operationId===op.id).every(r=>ids.has(r.id)));
 const completed=full.filter(op=>op.status==='Completed');
 const priced=completed.filter(op=>list.filter(r=>r.operationId===op.id).every(r=>r.cost!==null));
 const pricedIds=new Set(priced.map(op=>op.id)),paid=list.filter(r=>pricedIds.has(r.operationId));
 const tokenOps=completed.filter(op=>list.filter(r=>r.operationId===op.id).every(r=>r.input!==null&&r.output!==null));
 const tokenIds=new Set(tokenOps.map(op=>op.id));
 const costs=priced.map(op=>totals(list.filter(r=>r.operationId===op.id)).cost).sort((a,b)=>a-b);
 const quantile=q=>costs.length?costs[Math.max(0,Math.ceil(costs.length*q)-1)]:null;
 return {matched,full,completed,priced,tokenOps,costPerComplete:priced.length?totals(paid).cost/priced.length:null,
  tokensPerComplete:tokenOps.length?list.filter(r=>tokenIds.has(r.operationId)).reduce((a,r)=>a+r.input+r.output,0)/tokenOps.length:null,
  median:quantile(.5),p95:quantile(.95),partial:matched.length-full.length};
}
function showOperation(id) {
 const op=demoOperations.find(o=>o.id===id);if(!op)return;
 const list=demoRequests.filter(r=>r.operationId===id),t=totals(list);
 openDetail(op.workflow+' · '+op.id,`<p>DEMO · ${op.date} · ${op.status} · ${op.modality}</p><div class="callout">${dollars(t.cost)} known AI charge · ${num(t.input+t.output)} known tokens<p>${t.known}/${list.length} charges and ${t.tokenKnown}/${list.length} token pairs reported. All operation requests shown, independent of model filters.</p></div>${op.workflow.includes('Capture')||op.workflow==='Direct capture'?'<div class="listrow"><span>Saved locally</span><strong>$0 AI · 0 AI tokens</strong></div>':''}${list.map(r=>`<div class="listrow"><button class="linkbutton" data-request="${r.id}">${esc(r.stage)}${r.retry?' · retry':''} ↗<span class="path">${esc(r.model)}</span></button><strong>${r.input===null||r.output===null?'Tokens unavailable':short(r.input+r.output)+' tokens'} · ${dollars(r.cost)}</strong></div>`).join('')}<dl><dt>Cards drafted / saved</dt><dd>${op.cardsDrafted} / ${op.cardsSaved}</dd><dt>Outcome</dt><dd>${op.status}</dd></dl><div class="detailnote">One operation may make many requests. Card drafting inside ingest or Scout remains attributed to its parent workflow and to the Cards stage; these are two views of the same charges, never additive. Local capture has no model charge; transcription and processing can.</div>`);
}
function workflowTracking() {
 return `<div class="tiles"><button class="tile" data-info="Capture lifecycle"><strong>Capture</strong><span>Local save → extract → ingest → cards → index</span></button><button class="tile" data-info="Card unit cost"><strong>Cards</strong><span>Drafts, repair, saved cards, cost per saved card</span></button><button class="tile" data-info="Scout interaction cost"><strong>Scout</strong><span>Every turn, continuation, tool and compaction</span></button></div><p class="note">Track cost and input/output tokens per operation, stage, model and day. Real collection requires the shared on-device ledger in the implementation plan.</p>`;
}
function costBreakdowns(list) {
 const s=operationStats(list),t=totals(list),retry=list.filter(r=>r.retry),failed=list.filter(r=>r.status!=='Completed');
 const workflows=Object.keys(workflowStages).filter(w=>list.some(r=>r.workflow===w));
 const stages=[...new Set(list.map(r=>r.stage))];
 const cellTokens=(rs,key)=>rs.some(r=>r[key]!==null)?short(totals(rs)[key]):'Unavailable';
 const overviewTable=`<div class="tablewrap"><table><thead><tr><th>Workflow</th><th>Known cost</th><th>Input / output</th><th>Completed / whole operations</th><th>Cost / completed</th><th>Tokens / completed</th></tr></thead><tbody>${workflows.map(w=>{const rs=list.filter(r=>r.workflow===w),a=operationStats(rs),x=totals(rs);return `<tr><td><button class="linkbutton" data-workflow="${esc(w)}">${esc(w)} ↗</button><span class="path">${x.known}/${rs.length} charges known</span></td><td>${x.known?dollars(x.cost):'Unknown'}</td><td>${cellTokens(rs,'input')} / ${cellTokens(rs,'output')}</td><td>${a.completed.length} / ${a.full.length}</td><td>${a.costPerComplete===null?'Unavailable':dollars(a.costPerComplete)}<span class="path">${a.priced.length} fully priced completions</span></td><td>${a.tokensPerComplete===null?'Unavailable':short(a.tokensPerComplete)}<span class="path">${a.tokenOps.length} fully token-reported completions</span></td></tr>`}).join('')||'<tr><td colspan="6">No matching workflows.</td></tr>'}</tbody></table></div><p class="note">Unit averages include only whole completed operations with every required field reported. Failed, interrupted, partly filtered and missing-charge operations remain in total spend but are excluded from that average. ${s.partial} operations are partly hidden by request filters.</p>`;
 const stageTable=`<div class="tablewrap"><table><thead><tr><th>AI stage</th><th>Attempts</th><th>Input / output</th><th>Known cost</th><th>Charge coverage</th></tr></thead><tbody>${stages.map(stage=>{const rs=list.filter(r=>r.stage===stage),x=totals(rs);return `<tr><td><button class="linkbutton" data-stage="${esc(stage)}">${esc(stage)} ↗</button></td><td>${rs.length}</td><td>${cellTokens(rs,'input')} / ${cellTokens(rs,'output')}</td><td>${x.known?dollars(x.cost):'Unknown'}</td><td>${x.known}/${rs.length}</td></tr>`}).join('')}</tbody></table></div><p class="note">Stages partition the matching requests. Stage and workflow totals describe the same spend; never add them together. Token sums are reported portions; audio usage may be measured in seconds instead.</p>`;
 const cardOps=s.completed.filter(op=>op.cardsSaved>0&&list.filter(r=>r.operationId===op.id&&r.feature==='Cards').every(r=>r.cost!==null));
 const cardIds=new Set(cardOps.map(op=>op.id)),cardRows=list.filter(r=>cardIds.has(r.operationId)&&r.feature==='Cards');
 const saved=cardOps.reduce((a,op)=>a+op.cardsSaved,0),cardTokensKnown=cardRows.every(r=>r.input!==null&&r.output!==null);
 const ops=s.full.slice(-7).reverse();
 return panel(12,'What does each workflow consume?','Selected period, workflow and request filters · DEMO',overviewTable)+
 panel(12,'From capture to a usable note','AI stage totals · local capture itself uses 0 AI tokens and has $0 model charge',stageTable)+
 panel(6,'Card creation, down to each saved card','Card-stage charges only · includes drafts and repairs',`<div class="listrow"><span>Drafted / saved in whole completed operations</span><strong>${s.completed.reduce((a,op)=>a+op.cardsDrafted,0)} / ${s.completed.reduce((a,op)=>a+op.cardsSaved,0)}</strong></div><div class="listrow"><span>Fully priced saved-card cohort</span><strong>${saved} cards · ${cardOps.length} operations</strong></div><div class="listrow"><span>Card-stage cost / saved card</span><strong>${saved?dollars(totals(cardRows).cost/saved):'Unavailable'}</strong></div><div class="listrow"><span>Card-stage tokens / saved card</span><strong>${saved&&cardTokensKnown?short((totals(cardRows).input+totals(cardRows).output)/saved):'Unavailable'}</strong></div><p class="note">Embedded card generation is included once under the originating capture or Scout operation. No cost is divided by unsaved drafts. Local validation/editing does not make an AI request.</p>`,badge('DEMO','amber'))+
 panel(6,'Retries, failures and the expensive tail','Known charges · these diagnostic sets can overlap',`<div class="listrow"><span>Retry attempts · cost / tokens</span><strong>${dollars(totals(retry).cost)} / ${short(totals(retry).input+totals(retry).output)}</strong></div><div class="listrow"><span>Non-completed requests · cost / tokens</span><strong>${dollars(totals(failed).cost)} / ${short(totals(failed).input+totals(failed).output)}</strong></div><div class="listrow"><span>Median / p95 completed-operation cost</span><strong>${dollars(s.median)} / ${dollars(s.p95)}</strong></div><div class="listrow"><span>Fully priced completion sample</span><strong>${s.priced.length} operations</strong></div><p class="note">Retries can be necessary. Failed calls can still be charged. Missing charges remain excluded from known sums. Percentiles describe only fully priced completions, not all operations.</p>`)+
 panel(12,'Inspect an operation end to end','Whole matching operations · open the stage timeline',ops.map(op=>{const rs=list.filter(r=>r.operationId===op.id),x=totals(rs);return `<div class="issue"><span class="issueicon" style="background:var(--greenbg);color:var(--accent)">↗</span><div><h3>${esc(op.workflow)} · ${op.id}</h3><p>${op.date} · ${op.status} · ${rs.length} attempts · ${short(x.input+x.output)} known tokens</p></div><button data-operation="${op.id}">${dollars(x.cost)} ↗</button></div>`}).join('')||'<p>No whole operations match. Clear the model filter to see complete timelines.</p>');
}
const badge = (label, tone='') => `<span class="tag ${tone}">${esc(label)}</span>`;
const head = (title, sub, right='') => `<div class="panelhead"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;
const metric = (label,value,foot,detail,span=3) => `<button class="metric s${span}" data-info="${esc(detail||label)}"><span class="metriclabel">${label}<span>↗</span></span><strong class="metricvalue">${value}</strong><span class="metricfoot">${foot}</span></button>`;
const panel = (span, title, sub, body, right='') => `<section class="panel s${span}">${head(title,sub,right)}${body}</section>`;
const navigateButton = (section,label) => `<button class="linkbutton" data-nav="${section}">${label} ↗</button>`;
const demoBanner = () => `<div class="demo-banner">DEMO USAGE · Synthetic requests, prices and activity. Real vault inventory stays separate. No actual phone spend is available.</div>`;
const noData = (title,body) => `<div class="empty"><div class="bigicon">◌</div><h3>${title}</h3><p>${body}</p><button class="primary" data-action="demo">Explore sample data</button></div>`;
function bars(entries, color='var(--accent)', action='info') {
  const max = Math.max(1,...entries.map(x=>x[1]));
  return '<div class="bars">'+entries.map(([label,value,detail])=>`<button class="barrow" data-${action}="${esc(detail||label)}"><span>${esc(label)}</span><div class="track"><div class="fill" style="width:${value/max*100}%;background:${color}"></div></div><strong>${num(value)}</strong></button>`).join('')+'</div>';
}
function chart(points, label, money=false) {
  if (!points.length) return `<div class="empty"><h3>No recorded events in this period</h3><p>Try a wider period. Missing data is not zero activity.</p></div>`;
  const max = Math.max(1,...points.map(x=>x[1]));
  return `<div class="chart" role="group" aria-label="${esc(label)}">${points.map(([date,value])=>`<button style="height:${Math.max(2,value/max*100)}%" title="${esc(date)}: ${money?dollars(value):num(value)}" aria-label="${esc(date)}: ${money?dollars(value):num(value)}" data-chart="${esc(date+'|'+value+'|'+label+'|'+money)}"></button>`).join('')}</div><div class="chartaxis"><span>${points[0][0]}</span><span>${points.at(-1)[0]}</span></div>`;
}
function daySeries(list, value) {
  const map={}; list.forEach(r=>map[r.date]=(map[r.date]||0)+value(r));return Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0]));
}
function issue(title,sub,action,label='Inspect') { return `<div class="issue"><span class="issueicon">!</span><div><h3>${title}</h3><p>${sub}</p></div><button data-info="${esc(action)}">${label}</button></div>`; }
