function openDetail(title,body) {$('detailContent').innerHTML=`<h2>${esc(title)}</h2>${body}`;$('detail').showModal();}
function explain(key) {
 if(key==='YAML warnings'){openDetail('22 strict YAML warnings',`<p>Read-only parser findings. Limited scalar fallback preserved inventory counts. Sparkbox’s tolerant parser may still open these files.</p><dl>${V.parseErrors.map(e=>`<dt>${esc(e.path)}</dt><dd>${esc(e.error)}</dd>`).join('')}</dl><p>No files were repaired.</p>`);return;}
 if(key==='Incomplete extraction'){openDetail('Sources that need a closer look',`<p>${V.quality.title_only} title-only and ${V.quality.failed} failed extractions. Metadata quality describes extraction completeness.</p><button class="primary" data-quality="title_only">Browse title-only records</button> <button data-quality="failed">Browse failed records</button>`);return;}
 const entry=info[key]||[key,'Planned native drill-down. See PLAN.md for definition, data source, limitations and implementation phase. No live action runs from this prototype.'];
 openDetail(entry[0],`<p>${esc(entry[1])}</p><div class="detailnote">${demo?'Demo usage enabled. Vault inventory remains the actual snapshot.':'Actual vault snapshot. Phone-only usage and cost are unavailable.'}</div>`);
}
function render() {
 $('navigation').innerHTML=sections.map((s,i)=>`<button data-nav="${s}" class="${s===current?'active':''}" ${s===current?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[i]}"/></svg>${s}</button>`).join('');
 const copy={Overview:['A LITTLE PERSPECTIVE','Your garden, in view.','What you saved. What you returned to. What needs tending.'],Vault:['THE KNOWLEDGE YOU KEEP','Look inside your vault.','Follow a subject, inspect a source, see what connects.'],Habits:['YOUR OWN RHYTHM','How does this fit your day?','Capture, return, ask, review. Distinct actions, distinct stories.'],Recall:['BACK TO WHAT MATTERS','What is coming back?','A record of returning to ideas, without a score to chase.'],Scout:['AN AGENT WITH RECEIPTS','See what Scout did.','Conversations, context, requests and the changes they produced.'],Costs:['FOLLOW THE REQUEST','Where did the money go?','Recorded spend, explicit gaps, useful detail.'],Health:['A LITTLE TENDING','Know what needs attention.','Inspect incomplete records and missing evidence before acting.']}[current];
 $('eyebrow').textContent=copy[0];$('title').textContent=copy[1];$('subtitle').textContent=copy[2];
 $('freshness').innerHTML=`<span class="statusdot"></span>Mac snapshot · ${esc(new Date(V.generatedAt).toLocaleString('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))} IST`;
 $('scopeNote').className='scope-note'+(demo?' demo':'');
 $('scopeNote').textContent=demo?'Demo usage enabled · all usage, session and spend figures are synthetic. Current inventory stays actual.':'Actual snapshot · Knowledge/ + legacy Sources/ · current inventory ignores event period · phone usage unavailable';
 $('demo').checked=demo;
 $('content').innerHTML=({Overview:overview,Vault:vault,Habits:habits,Recall:recall,Scout:scout,Costs:costs,Health:health})[current]();
}
function go(s){current=s;query='';kind='All';quality='All';page=0;model='All';purpose='All';costWorkflow='All';history.replaceState(null,'','#'+s.toLowerCase());render();window.scrollTo(0,0);}
function notify(message){$('toast').textContent=message;$('toast').className='show';setTimeout(()=>$('toast').className='',3000);}
function exportView() {
 let data=current==='Vault'?{dataClass:'Actual Mac snapshot',notes:filteredNotes()}:current==='Scout'||current==='Costs'||(current==='Habits'&&demo)?{dataClass:demo?'Synthetic demo':'Unavailable',requests:demo?rows(current==='Scout'):[],coverage:demo?totals(rows(current==='Scout')):null}:current==='Recall'?{dataClass:'Actual retained history',cards:V.cards}:current==='Health'?{dataClass:'Actual research findings',warnings:V.parseErrors,limitations:V.limitations}:{dataClass:'Actual snapshot',counts:V.counts,sourceQuality:V.quality,usageAvailable:false};
 const payload={view:current,eventPeriod:range,requestFilters:{model,purpose,workflow:current==='Costs'?costWorkflow:'All'},operations:demo&&['Costs','Scout'].includes(current)?operationStats(rows(current==='Scout')).full:[],inventoryAsOf:V.generatedAt,scope:V.scope,usageDemo:demo,...data};
 const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download='sparkbox-'+current.toLowerCase()+(demo?'-demo':'-snapshot')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exported selected view.');
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,tr[data-note],tr[data-request]');if(!b)return;
 if(b.dataset.operation){showOperation(b.dataset.operation);}
 else if(b.dataset.workflow){costWorkflow=b.dataset.workflow;render();}
 else if(b.dataset.stage){const rs=rows().filter(r=>r.stage===b.dataset.stage),t=totals(rs);openDetail(b.dataset.stage+' · DEMO',`<p>${rs.length} attempts · ${num(t.input)} known input · ${num(t.output)} known output · ${dollars(t.cost)} known charge · ${t.missing} missing charges.</p>${rs.slice(-12).reverse().map(r=>`<div class="listrow"><button class="linkbutton" data-request="${r.id}">${r.id} ↗</button><strong>${dollars(r.cost)}</strong></div>`).join('')}`);}
 else if(b.dataset.nav){if($('detail').open)$('detail').close();go(b.dataset.nav);}
 else if(b.dataset.info)explain(b.dataset.info);
 else if(b.dataset.kind){kind=b.dataset.kind;current='Vault';page=0;render();$('notetable').scrollIntoView({block:'center'});}
 else if(b.dataset.category){kind=b.dataset.category;current='Vault';page=0;render();}
 else if(b.dataset.quality){$('detail').close();current='Vault';kind='Sources';quality=b.dataset.quality;page=0;render();}
 else if(b.dataset.note!==undefined){const n=V.notes[Number(b.dataset.note)];openDetail(n.title,`<p>${esc(n.path)}</p><dl><dt>Kind</dt><dd>${n.kind}</dd><dt>Captured</dt><dd>${n.captured||'Unknown'}</dd><dt>Extraction quality</dt><dd>${n.kind==='Sources'?n.quality:'Not applicable'}</dd><dt>Card blocks</dt><dd>${n.cards}</dd><dt>Topics recorded</dt><dd>${esc(n.topics.join(', ')||'None recorded')}</dd></dl><div class="detailnote">Metadata preview only. Native implementation will open this note in Sparkbox. No note is edited here.</div>`);}
 else if(b.dataset.request){const r=demoRequests.find(x=>x.id===b.dataset.request);openDetail(r.id+' · '+r.feature,`<p>Synthetic request. No real provider data.</p><dl>${Object.entries(r).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(k==='cost'?dollars(v):v)}</dd>`).join('')}</dl><div class="detailnote">Cached tokens are included in input. Reasoning tokens are included in output. Missing charge is unknown.</div>`);}
 else if(b.dataset.session){const list=rows(true).filter(r=>r.session===b.dataset.session),t=totals(list);openDetail(b.dataset.session,`<p>Synthetic session · ${list.length} attempts · ${dollars(t.cost)} known spend · ${t.missing} unknown charges.</p>${list.map(r=>`<div class="listrow"><span>${r.id} · ${r.purpose}</span><strong>${dollars(r.cost)}</strong></div>`).join('')}<p>Native view links to the existing per-session Usage screen.</p>`);}
 else if(b.dataset.feature){const list=rows().filter(r=>r.feature===b.dataset.feature),t=totals(list);openDetail(b.dataset.feature+' · demo spend',`<p>${list.length} synthetic attempts. ${dollars(t.cost)} known charge. ${t.missing} missing charges.</p>${list.slice(-12).reverse().map(r=>`<div class="listrow"><button class="linkbutton" data-request="${r.id}">${r.id} ↗</button><strong>${dollars(r.cost)}</strong></div>`).join('')}`);}
 else if(b.dataset.chart){const [date,value,label,money]=b.dataset.chart.split('|');openDetail(date,`<p>${esc(label)}: <strong>${money==='true'?dollars(Number(value)):num(value)}</strong></p><div class="detailnote">${label.startsWith('Demo')?'Synthetic demonstration data.':label.includes('review')?'Actual retained review entries, grouped in UTC.':'Actual surviving source records grouped by captured date. Not app usage.'}</div>`);}
 else if(b.dataset.action==='demo'){demo=true;render();}
 else if(b.dataset.action==='prev'){page=Math.max(0,page-1);$('notetable').innerHTML=noteRows();}
 else if(b.dataset.action==='next'){page++;$('notetable').innerHTML=noteRows();}
 else if(b.dataset.action==='export')exportView();
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-note],tr[data-request]'))e.target.click();});
document.addEventListener('input',e=>{
 if(e.target.id==='search'){query=e.target.value;page=0;$('notetable').innerHTML=noteRows();}
 if(e.target.id==='budget'){const value=Number(e.target.value);if(Number.isFinite(value)&&value>=1&&value<=10000){budget=value;$('budgetamount').textContent=dollars(budget);$('budgetfill').style.width=Math.min(100,totals(rows()).cost/budget*100)+'%';}}
});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='demo'){demo=e.target.checked;render();}if(id==='period'){range=e.target.value;render();}if(id==='kind'){kind=e.target.value;page=0;$('notetable').innerHTML=noteRows();}if(id==='quality'){quality=e.target.value;page=0;$('notetable').innerHTML=noteRows();}if(id==='order'){order=e.target.value;page=0;$('notetable').innerHTML=noteRows();}if(id==='workflow'){costWorkflow=e.target.value;render();}if(id==='model'){model=e.target.value;render();}if(id==='purpose'){purpose=e.target.value;render();}});
$('theme').onclick=()=>document.body.classList.toggle('light');$('export').onclick=exportView;$('close').onclick=()=>$('detail').close();
$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const b=$('detail').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('detail').close();}});
window.addEventListener('hashchange',()=>{current=sections.find(x=>x.toLowerCase()===location.hash.slice(1))||'Overview';render();});
render();
